    let result = operand[0];
    for (let i = 1; i < operand.length; i++) {
        let op = operator[i];
        if (op === '+') {
            result += operand[i];
        } else if (op === '-') {
            result -= operand[i];
        } else if (op === '*') {
            result *= operand[i];
        } else if (op === '//') {
            result = Math.floor(result / operand[i]);
        } else if (op === '**') {
            result = Math.pow(result, operand[i]);
        }
    }
    return result;
}

